    id: "bus-2024-hl-s3-q1ci", topicId: "business-3-20", conceptId: "unfair-dismissal-grounds",
    section: "3", questionRef: "2024 HL Section 3 Q1(C)(i)",
    questionText: "List three grounds, under which a dismissal can be deemed unfair according to the Unfair Dismissals Act 1977/2015.",
    tariffModel: {"kind":"bestNofParts","notation":"3@2m","answer":3,"ofParts":8,"perPart":2}, totalMarks: 6,
